public class BarChartPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int[] values, int width, int height) {
        java.awt.image.BufferedImage img =
                new java.awt.image.BufferedImage(width, height, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            BarChartPainter.paint(g, values, width, height);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(new int[] { 4, 8, 2, 6 }, 80, 80);
            check("white above bar 0 (10,20)", "#FFFFFF", pixel(a, 10, 20));
            check("bar 0 body (10,60)", "#0000FF", pixel(a, 10, 60));
            check("bar 1 reaches the top (30,10)", "#0000FF", pixel(a, 30, 10));
            check("white above the short bar 2 (50,40)", "#FFFFFF", pixel(a, 50, 40));
            check("bar 3 body (70,50)", "#0000FF", pixel(a, 70, 50));
            java.awt.image.BufferedImage b = render(new int[] { 2, 1 }, 40, 40);
            check("full-height bar (10,10)", "#0000FF", pixel(b, 10, 10));
            check("white above half bar (30,10)", "#FFFFFF", pixel(b, 30, 10));
            check("half bar body (30,32)", "#0000FF", pixel(b, 30, 32));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

