import java.awt.Color;
import java.awt.Graphics2D;

public class BarChartPainter {

    public static void paint(Graphics2D g, int[] values, int width, int height) {
        g.setColor(Color.WHITE);
        g.fillRect(0, 0, width, height);
        int max = 0;
        for (int v : values) {
            max = Math.max(max, v);
        }
        if (max == 0) {
            return;
        }
        int slotWidth = width / values.length;
        g.setColor(Color.BLUE);
        for (int i = 0; i < values.length; i++) {
            int barHeight = values[i] * height / max;
            g.fillRect(i * slotWidth, height - barHeight, slotWidth, barHeight);
        }
    }
}
